import pandas as pd

def clean(df):
    df = df.copy()
    df['Price'] = pd.to_numeric(
        df['Price'].astype(str).str.strip().str.replace(r'[$,]', '', regex=True),
        errors='coerce'
    )
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    df['Quantity'] = df['Quantity'].abs()

    region_map = {
        'north': 'North', 'south': 'South', 'east': 'East', 'west': 'West',
        'wst': 'West', 'suoth': 'South'
    }

    def norm_region(x):
        if pd.isna(x):
            return x
        s = str(x).strip()
        return region_map.get(s.lower(), s)

    df['Region'] = df['Region'].map(norm_region)
    df['Category'] = df['Category'].astype('string').str.strip()
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    d = clean(df)
    d = d[d['Category'].str.lower() == 'electronics']
    d = d.dropna(subset=['Region'])
    totals = d.groupby('Region')['Revenue'].sum()
    return {str(k): float(v) for k, v in totals.items()}
